  'settings.connections.typeHint': '«هیچ» و «مستقیم» یک معنا ندارند. هیچ بی‌اثر است: هیچ اتصالی را نام نمی‌برد و هرگز به کار نمی‌رود، پس فقط تا وقتی می‌ماند که پر کردنش را تمام کنی. مستقیم یک انتخاب واقعی است: از اتصال خودِ این دستگاه بیرون می‌رود و برای میزبان‌هایی که پایین نام برده شده‌اند هر پروکسی را دور می‌زند. این‌طوری یک NAS را از پروکسیِ کل برنامه بیرون می‌گذاری. ردیفی که پالایه‌اش با میزبان جور است بر ردیف بی‌پالایه برتری دارد، پس ردیف مستقیمِ پالایه‌دار همیشه بر پروکسیِ همه‌گیر پیروز می‌شود.',
