  'settings.reconnect.policyHint': 'اتصال‌های دوباره خودکار تنها از یک جا شلیک می‌شوند و آن جا این صفحه نیست. یکی وقتی آغاز می‌شود که خودِ موتور دانلود پس از مکثی تلاش دیگری بخواهد، و میزبان با همین زبان می‌گوید که محدودیت به این نشانی بسته است. تا وقتی صف متوقف است هرگز اجرا نمی‌شود، چون راه‌اندازی دوباره روتر دانلودهای در جریان را قطع می‌کند. تا وقتی اتصال دوباره کامل پیکربندی نشده باشد هم هرگز اجرا نمی‌شود. هر بار تنها یکی اجرا می‌شود: درخواست دوم به‌جای کشمکش بر سر روتر، منتظر حکم اولی می‌ماند. و اگر نشانی تکان نخورد، چیزی جلو انداخته نمی‌شود و همان مکث معمول پیش از تلاش بعدی به راه خود می‌رود.',

