  'settings.chunks': 'اتصال‌ها برای هر دانلود (0 = خودکار)',
  'settings.chunksHint': 'یک دانلود چند اتصال باز می‌کند وقتی چیز دقیق‌تری اعمال نمی‌شود. یک قاعده، یا یک دانلود مشخص، می‌تواند عدد خودش را بگوید و بر این می‌چربد. میزبانی که کمتر تحمل می‌کند باز هم کمتر می‌گیرد: محدودیت میزبان فقط می‌تواند عدد را پایین بیاورد، هرگز بالا نمی‌برد. با ۰ تصمیم به برنامه واگذار می‌شود. بیش از یک مشت اتصال روی میزبانی که برای هر فایل محدودیت می‌گذارد چیزی به دست نمی‌دهد و راهی مطمئن برای نشان‌دار شدن یک حساب است.',
  'task.chunks': 'اتصال‌ها (0 = تنظیم سراسری)',
  'task.chunksHint': 'همین یک دانلود چند اتصال باز می‌کند. بر تنظیم سراسری و بر هر قاعده‌ای که آن را گذاشته می‌چربد، اما هرگز بر میزبان: میزبانی که کمتر تحمل می‌کند باز هم کمتر می‌گیرد. با ۰ این استثنا برداشته می‌شود و تصمیم دربارهٔ عدد دوباره جای دیگری گرفته می‌شود.',
