  'props.name': 'نام',
  'props.nameHint': 'یک نام فایل، هرگز یک مسیر: هر چه پوشه‌ها را بنویسد تا یک نام کوتاه می‌شود. دانلود تمام‌شده روی دیسک هم تغییر نام می‌دهد تا فهرست و پوشه با هم در تناقض نیفتند. دانلودی که در حال اجراست همان فایلی را که موتورش باز نگه داشته حفظ می‌کند و نام تازه را هنگام پایان می‌گیرد. دانلودی که هنوز شروع نشده بی‌درنگ آن را می‌گیرد. نام به یک فایل تعلق دارد، پس این کادر فقط برای یک ردیف پیشنهاد می‌شود.',
