  'settings.about.cryptoNoTag': 'به Destination Tag یا Memo نیازی نیست.',
  'settings.about.coffeeIntro': 'پرداخت از طریق Buy Me a Coffee انجام می‌شود. به حساب کاربری نیازی ندارید.',
  'settings.about.paypalIntro': 'پرداخت از طریق PayPal انجام می‌شود، با حساب PayPal خودتان یا با کارت و بدون حساب.',
