  'common.copy': 'کپی',
  'common.copied': 'کپی شد',
  'settings.about.coffee': 'اگر KnightLoader جایش را روی سرور یا رایانه‌ات به دست آورده، سکه‌ای به شوالیه‌ات بینداز: به پوشش هزینه‌ها کمک می‌کند و پروژه را زنده نگه می‌دارد. و قلب این شوالیه را کمی تندتر می‌زند. پایین سه راه هست، هرکدام که برایت مناسب است.',
  'settings.about.report': 'مشکل، خواسته یا پیشنهادی دارید؟ در GitHub مسئله‌ای باز کنید یا ایمیل بفرستید.',
  'settings.about.version': 'نسخه',
