  'settings.about.mail': 'ایمیل',
  'settings.about.mailSubject': 'بازخورد',
  'settings.scripts.subtitle': 'KnightLoader را با جاوااسکریپت خودتان خودکار کنید، که با رویدادی یا به‌درخواست اجرا می‌شود.',
  'settings.scripts.listTitle': 'اسکریپت‌های شما',
  'settings.scripts.add': 'افزودن اسکریپت',
  'settings.scripts.empty': 'هنوز اسکریپتی نیست',
  'settings.scripts.emptyHint':
    'اسکریپت وقتی اتفاقی می‌افتد جاوااسکریپت خودت را اجرا می‌کند، مثل تمام شدن یک دانلود، شکست خوردن یک دانلود یا بی‌کار شدن صف. می‌توانی آن را هر وقت خواستی هم اجرا کنی، از «اجرای آزمایشی» همین‌جا یا از گزینهٔ «اجرای اسکریپت» در منوی کلیک‌راست فهرست دانلودها. برای شروع یکی اضافه کن.',
  'settings.scripts.loadFailed':
    'اسکریپت‌ها بارگذاری نشدند. اگر این بیلد هنوز موتور خودکارسازی را ندارد، این صفحه چیزی برای نشان دادن ندارد. وقتی داشت دوباره امتحان کن.',
