    '// این اسکریپت روی محرکی که بالا انتخاب شده اجرا می‌شود.\n// API سندباکسی که روی آن اجرا می‌شود هنوز در حال تکمیل است. وقتی آماده شد، تنظیمات › راهنما را ببین.\n',
