  'settings.access.relay.title': 'بازپخش پروژه',
  'settings.access.relay.body': 'رله یک واسط است که همه نمونه‌های شما را از بیرون شبکه خانگی، یعنی از هر جا، در دسترس می‌کند. این یکی را پروژه رایگان فراهم می‌کند.',
