  'settings.access.relay.leadProject': 'بدون هیچ تنظیمی کار می‌کند. هر چه نمونه‌های شما به هم می‌گویند رمزگذاری شده است، و کلید فقط دست شماست.',
  'settings.access.relay.address': 'نشانی',
  'settings.access.relay.seesButton': 'چه می‌بیند؟',
  'settings.access.relay.seesTip': 'برای رله دیده نمی‌شود: پیوندها، دانلودها، فایل‌ها و توکن دسترسی تو.\n\nبرای رله دیده می‌شود: نشانی‌های IP نمونه‌هایت و اینکه کِی چیزی می‌فرستند.\n\nاین را نمی‌شود با رمزگذاری پنهان کرد. اگر آزارت می‌دهد، رلهٔ خودت را راه بینداز.',
  'settings.access.relay.none': 'بدون بازپخش',
  'settings.access.relay.noneHint': 'هیچ رله‌ای فعال نیست. در همان شبکه، یعنی شبکه خانگی شما، نمونه‌ها همچنان خودشان یکدیگر را پیدا می‌کنند. میان شبکه‌های مختلف به هم نمی‌رسند، پس دسترسی از راه دور ممکن نیست.',
