  'settings.access.ownRelay.serveLabel': 'این نمونه را به عنوان رله استفاده کن',
  'settings.access.ownRelay.serveHint': 'تنها زمانی کار می‌کند که این نمونه از بیرون در دسترس باشد، مثلاً از طریق Nginx Proxy Manager و دامنه خودتان.',
  'settings.access.ownRelay.serveClients': 'هم‌اکنون {count} متصل است.',
  'settings.access.ownRelay.addressLabel': 'نشانی',
