  'settings.access.ownRelay.save': 'ذخیره',
  'settings.access.ownRelay.everyInstance': 'این نشانی فقط برای همین نمونه است. آن را روی هر نمونه وارد کنید.',
  'settings.access.ownRelay.containerLabel': 'به‌عنوان ظرف مستقل',
  'settings.access.ownRelay.containerHint': 'اگر هیچ‌کدام از نمونه‌هایت از بیرون در دسترس نیست، رله باید جای دیگری باشد، روی سرورت یا یک VPS کوچک. کانتینر را از Unraid Community Applications یا با دستور زیر نصب کن.\n\nکانتینر به هیچ تنظیمی نیاز ندارد: اجرایش کن، نشانی‌اش را بالا وارد کن، تمام. چیزی ذخیره نمی‌کند، پس چیزی هم برای پشتیبان‌گیری نیست.',
  'settings.access.tokens.title': 'توکن‌های API',
