  'settings.access.identity.nameHint': 'هنگام جفت‌سازی و در کد QR زیر اول همین پیشنهاد می‌شود، به‌جای هر نامی که سیستم‌عامل یا محیط اجرای کانتینر به این دستگاه داده است. اختیاری است: خالی بگذار تا همان نام به کار برود.',
  'settings.access.identity.domainsLabel': 'دامنه‌های شناخته‌شده',
  'settings.access.identity.domainsHint': 'هر دامنه اولین باری که درخواستی از طریقش برسد خودکار به خاطر سپرده می‌شود، و حتی وقتی درخواست‌های بعدی از طریق IP شبکهٔ محلی بیایند در این فهرست می‌ماند. اگر دامنه‌ای از قبل پیکربندی شده اما هنوز هیچ درخواستی از طریقش نیامده، دستی اضافه‌اش کن. هر خط یک نشانی کامل، مثلاً https://kl.example.com.',
  'settings.access.cardTitle': 'اتصال نمونه‌ها و دسترسی از راه دور',
  'settings.access.phrase.body': 'یک عبارت همهٔ KnightLoaderهایت را به هم وصل می‌کند. اینجا بسازش و بعد در نمونه‌های دیگرت بچسبانش. به هیچ حساب یا ورودی نیاز نداری و چیزی هم برای پیکربندی نیست.',
  'settings.access.phrase.noPasswordWarning': 'این نمونه رمز عبور ندارد. عبارت به هر نمونه‌ای که با آن وصل کنید می‌رسد، پس هرکس اینجا بتواند آن را بخواند به همه می‌رسد، نه فقط به این یکی. بهتر است اول بالا رمز بگذارید.',
  'settings.access.phrase.activate': 'ساخت عبارت',
  'settings.access.phrase.howLead': 'دوازده واژه، همین. این کاری است که باید کرد و این چیزی است که رخ می‌دهد:',
  'settings.access.phrase.howStep1': 'در این نمونه «{button}» را بزنید. دوازده واژه ظاهر می‌شود.',
  'settings.access.phrase.howStep2': 'روی دستگاه دیگر KnightLoader را باز کنید، به همین صفحه بیایید، «{button}» را بزنید و دوازده واژه را تایپ کنید.',
  'settings.access.phrase.howStep3': 'تمام! هر نمونه اکنون در دیگری زیر «نمونه‌ها» ظاهر می‌شود و می‌توانی هرکدام را از هرکدام اداره کنی. با رلهٔ روشن، نمونه‌هایت از بیرون شبکه‌ات در دسترس‌اند.',
  'settings.access.phrase.howWhat': 'واژه‌ها یک راز هستند، نه یک نشانی. هر نمونه از آن‌ها دو کلید می‌سازد: یکی برای یافتن دیگران و یکی برای رمزگذاری.\n\nبرای یافتن یکدیگر، هر نمونه خودش به همان نقطه دیدار در اینترنت زنگ می‌زند. هر که همان کلید را نشان دهد وصل می‌شود. برای همین هیچ‌کدام از نمونه‌های شما لازم نیست از بیرون در دسترس باشد.\n\nنقطه دیدار نمی‌تواند بخواند. هرگز واژه‌های شما را نمی‌بیند و هرچه از آن می‌گذرد با کلید دوم رمزگذاری شده است.',
