  'settings.resolvers.intro': 'پیکربندی بک‌اند yt-dlp، که سایت‌های رسانه و پخش زنده‌ای را که خودِ yt-dlp پشتیبانی می‌کند می‌گیرد. اینکه اصلاً کدام سرویس یک پیوند مشخص را پردازش کند (yt-dlp، یک حساب debrid یا سایدکار headless JD) با ترتیب مسیریابی در صفحهٔ حساب‌ها تعیین می‌شود. این صفحه تعیین می‌کند yt-dlp پس از اینکه پیوندی به آن سپرده شد چه کند.',
