  'settings.torrents.portHint': 'درگاهی که این نمونه اتصال‌های ازدحام را روی آن می‌شنود. 0 باعث می‌شود موتور تورنت خودش یکی انتخاب کند.',
  'settings.torrents.portMapHint': 'از روتر می‌خواهد درگاه بالا را از طریق UPnP به این دستگاه هدایت کند، تا همتاهای پشت روتری دیگر هم بتوانند به آن برسند. همهٔ روترها از این پشتیبانی نمی‌کنند، و برخی درخواست را می‌پذیرند بدون آنکه واقعاً کار کند.',
  'settings.torrents.portMapButton': 'تلاش برای نگاشت UPnP',
  'settings.torrents.portMapping': 'در حال پرسیدن از روتر…',
  'settings.torrents.portMapNeedsPort': 'پیش از هدایت، اول یک درگاه در بالا تنظیم کن. با 0، روتر جایی برای هدایت ندارد.',
  'settings.torrents.portMapConfirmed': 'تأیید شد: درگاه {port} نگاشت شده و دسترس‌پذیر بودن آن تأیید شده است.',
  'settings.torrents.portMapUnconfirmed': 'روتر درخواست را پذیرفت، اما نمی‌شود تأیید کرد که هدایت درگاه واقعاً کار می‌کند. بعضی روترها درخواست را بی‌صدا می‌پذیرند و اجرایش نمی‌کنند. یک بررسی اتصال از بیرون شبکه امتحان کن.',
  'settings.torrents.portMapFailed': 'درگاه نگاشت نشد: {error}',
  'settings.torrents.portMapUnavailable': 'این نسخه هنوز نگاشت درگاه را ارائه نمی‌دهد.',
  'settings.torrents.networkTitle': 'کشف همتا',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'با استفاده از دیگر کلاینت‌های BitTorrent به‌عنوان فهرست توزیع‌شده، بدون هیچ ردیابی همتا پیدا می‌کند.',
  'settings.torrents.pex': 'تبادل همتا (PEX)',
  'settings.torrents.pexHint': 'همتاهای شناخته‌شده را با همتاهای متصل‌شده مبادله می‌کند، تا ازدحامی با همتای کم سریع‌تر پیدا شود.',
  'settings.torrents.privateNote': 'یک تورنت خصوصی به‌محض اینکه فراداده‌اش شناخته شود هر دو را خودکار خاموش می‌کند، هر چه اینجا تنظیم شده باشد: برای فایل .torrent بارگذاری‌شده بلافاصله، و برای پیوند مگنت به‌محض اینکه فرادادهٔ خودش از ازدحام برسد. بیشتر ردیاب‌های خصوصی حساب‌هایی را که از هر کدام از این دو استفاده کنند مسدود می‌کنند.',
  'settings.torrents.engineNote': 'نسبت سید و مدت سید به هر تورنتی که این موتور شروع می‌کند می‌رسند. درگاه فقط به نخستین تورنتی می‌رسد که از آخرین راه‌اندازی مجدد این نمونه شروع شده، چون موتور کلاینت تورنت خودش را یک بار می‌سازد و دیگر هرگز از نو نمی‌سازد. تغییر بعدی درگاه باز هم درست ذخیره می‌شود و پس از راه‌اندازی مجدد بعدی اعمال می‌شود. محدودیت آپلود فعلاً فقط ذخیره و اعتبارسنجی می‌شود؛ موتور هنوز راهی برای اعمالش بر دانلودی در حال اجرا ندارد. برای یک تورنت معمولی، DHT و PEX در پایین هم هنوز اعمال نمی‌شوند: پیش‌فرض خودِ این نمونه به دانلود در حال اجرا نمی‌رسد، پس تورنت با هر دو روشن سید می‌کند، هر چه اینجا تنظیم شده باشد. تورنت خصوصی حالت دیگری است که در یادداشت پایین‌تر آمده. دکمهٔ هدایت پایین‌تر با این حال کار می‌کند: از روتر می‌خواهد شمارهٔ درگاهی را که بالا وارد شده هدایت کند، چه تورنتی روی آن گوش بدهد چه نه.',
