  'onboarding.welcome.title': 'به KnightLoader خوش آمدی',
  'onboarding.welcome.body': 'KnightLoader یک مدیر دانلود خودمیزبان است. پیوندی را بچسبان یا رها کن تا بک‌اند مناسبش آن را بگیرد: موتور داخلی برای پیوندهای سادهٔ فایل، yt-dlp برای صفحه‌های رسانه‌ای، یک سرویس debrid برای میزبان‌هایی که از قبل برایشان پول می‌دهی، یا یک JDownloader بدون رابط گرافیکی برای بقیه. این گشت کوتاه همان یک تنظیمی را نشان می‌دهد که ارزش دارد پیش از شروع بررسی‌اش کنی.',
  'onboarding.welcome.langLabel': 'زبان رابط کاربری',
  'onboarding.folder.title': 'فایل‌ها کجا باید فرود بیایند؟',
  'onboarding.folder.body': 'این پوشه‌ای است که دانلودهای تمام‌شده در آن نوشته می‌شوند. مسیری را تایپ کن یا سرور را برای پیدا کردن یکی مرور کن. هر وقت خواستی می‌توانی آن را از صفحهٔ تنظیمات عمومی عوض کنی.',
  'onboarding.accounts.title': 'میزبان‌های ویژه، هر وقت بخواهی',
  'onboarding.accounts.body': 'صف بدون هیچ حسابی هم کار می‌کند. هر وقت روی میزبان یا سرویس debrid ای که از قبل برایش پول می‌دهی سرعت کامل خواستی، اطلاعات ورودش را در حساب‌ها اضافه کن. هیچ‌کدام از این‌ها لازم نیست الان تنظیم شود.',
  'onboarding.accounts.link': 'باز کردن حساب‌ها',
  'onboarding.finished.title': 'آماده‌ای',
  'onboarding.finished.body': 'با این، گشت به پایان می‌رسد. صفحه راهنما زیر تنظیمات، توضیح کاملی از هر چیز دیگری که این نسخه انجام می‌دهد دارد، و بیشتر کنترل‌ها توضیح خودشان را پشت یک آیکون (i) دارند.',

