  'settings.nav.shortcuts': 'میان‌برها',
  'settings.shortcuts.subtitle': 'هر فرمانی که با یک میان‌بر صفحه‌کلید پیش‌فرض عرضه می‌شود، گروه‌بندی‌شده بر اساس محل کاربردش. یک انتساب را تغییر بده، یا آن را به حالت پیش‌فرض بازنشانی کن.',
  'settings.shortcuts.empty': 'هنوز هیچ فرمانی میان‌بر پیش‌فرض ندارد.',
  'settings.shortcuts.change': 'تغییر',
  'settings.shortcuts.reset': 'بازنشانی',
  'settings.shortcuts.resetAll': 'بازنشانی همه به حالت پیش‌فرض',
  'settings.shortcuts.resetAllConfirmTitle': 'همه میان‌برها بازنشانی شوند؟',
  'settings.shortcuts.resetAllConfirmBody': 'هر میان‌بر دوباره‌تنظیم‌شده به حالت پیش‌فرض خود برمی‌گردد. این کار قابل بازگشت نیست.',
  'settings.shortcuts.resetAllConfirm': 'بازنشانی همه',
