  'settings.downloads.diskTitle': 'فضای دیسک',
  'settings.downloads.diskHint': 'سه عدد که دانلودها را پیش از پر شدن دیسک نگه می‌دارند. هر سه به بایت‌های آزاد روی دیسکی اشاره دارند که دانلود روی آن نوشته می‌شود، پس پوشهٔ کاری روی دیسک دیگر روی همان دیسک اندازه گرفته می‌شود. صفر یک عدد را خاموش می‌کند. از هر سیستمی نمی‌شود پرسید چقدر فضا آزاد است، و جایی که پاسخی در دسترس نیست هرگز چیزی نگه داشته نمی‌شود، چون نگهبانی که وقتی نمی‌داند جلوی کار را بگیرد یک دستگاه کاملاً سالم را متوقف می‌کرد.',
