  'settings.rules.action.category': 'دسته',
  'settings.rules.action.categoryHint': 'پیوندهای همخوان را در یکی از کشوهای فهرست دسته‌ها، پایین‌تر در همین صفحه، بایگانی می‌کند، کشویی که پوشه، جایگاه در صف، کلید استخراج و قاعدهٔ تداخل خودش را با خود می‌آورد. دست‌نخورده که بماند، هیچ قاعده‌ای دربارهٔ آن نظری ندارد و پیوند بایگانی‌نشده می‌ماند. اگر همین قاعده پوشهٔ دانلودی هم نام ببرد، آن پوشه برنده است و کشو باز هم باقی چیزها را می‌دهد. نام بردن کشویی که حذف شده هنگام ذخیره رد می‌شود، چون قاعده‌ای که به کشوی نبوده اشاره کند برای هر پیوندی که با آن بخواند اصلاً هیچ کاری نمی‌کند، بی‌صدا.',
