  'detail.retriesHint': 'اینکه این دانلود پس از یک شکست چند بار دوباره تلاش شده است. همان لحظه‌ای که دانلود تمام می‌شود این شمارنده به صفر برمی‌گردد، پس یک ردیف تمام‌شده صفر نشان می‌دهد، حتی اگر چهار بار طول کشیده باشد. اینکه چند تلاش باقی مانده اینجا نوشته نمی‌شود: سقف آن به علت و به میزبان بستگی دارد و این صفحه نمی‌تواند حسابش کند.',
