  'detail.gaveUp': 'تلاش دوباره‌ای در کار نیست',
  'detail.gaveUpHint': 'اینجا از روی عمد کار تمام شده است، نه چون تلاش‌ها ته کشیده‌اند: یک کپچا، یک دیسک پر، یا قاعده‌ای که برای این میزبان «هرگز» می‌گوید. بالا بردن شمار تلاش‌های دوباره اینجا چیزی را عوض نمی‌کند. خودِ این نشانه در پایگاه‌داده نوشته نمی‌شود، پس پس از یک راه‌اندازی دوباره از بین می‌رود، هرچند دلیلش سر جایش می‌ماند.',
