  'detail.rulesHint': 'قواعدی که هنگام آماده شدن این پیوند روی آن عمل کرده‌اند، به همان ترتیبی که اجرا شدند. با نام نگه داشته می‌شوند: قاعده‌ای که از آن پس نامش عوض شده دیگر پیدا نمی‌شود، و قاعده‌ای که هرگز نامی نداشت با همان جایگاهی نگه داشته می‌شود که آن زمان داشت. با کلیک روی یکی، همان قاعده در ویرایشگر قواعد باز می‌شود.',
