  'notifications.event.captchaWaiting': 'یک کپچا منتظر است',
  'notifications.event.captchaWaitingHint': 'پنجرهٔ کپچا در هر حال در همین زبانه باز می‌شود. در آغاز روی «چیزی نشان نده» است، چون تا وقتی به آن نگاه می‌کنی همان پنجره خودش پیام است. روی اعلان سیستمی بگذارش، آن‌وقت کپچایی در یک زبانهٔ پس‌زمینه هم پیش از آنکه میزبان نشست را دور بیندازد به تو می‌رسد.',
