  'notifications.systemUnavailable': 'اعلان‌های سیستمی اینجا در دسترس نیستند: مرورگرت آن‌ها را تنها روی HTTPS یا روی localhost عرضه می‌کند. هر چیزی که روی این کارت است باز هم در خود برنامه نشان داده می‌شود.',
  'notifications.systemBlocked': 'مرورگرت اعلان‌ها را برای این نشانی مسدود کرده است. ردیف‌هایی که روی «اعلان سیستمی» هستند به‌جایش در خود برنامه دیده می‌شوند، تا وقتی در تنظیمات سایتِ مرورگرت دوباره اجازه‌شان بدهی.',
  'notifications.systemNotGranted': 'مرورگر اجازه نداد، پس این رویداد در خود برنامه می‌ماند. یک بار دیگر «اعلان سیستمی» را برگزین تا دوباره پرسیده شود.',
