  'volume.unsizedHint': 'در {n} تا از این دانلودها میزبان هرگز اندازه‌ای نگفته است. این‌ها چیزی به جمع اضافه نمی‌کنند، پس عدد واقعی از آنچه اینجا کشیده شده بالاتر است.',
  'volume.trimmedHint': 'تاریخچه به سقف خودش رسیده است، پس هر چیزی قدیمی‌تر از قدیمی‌ترین مدخل آن، از این نمودار هم غایب است. اگر می‌خواهی سابقهٔ بلندتری داشته باشی، سقف تاریخچه را در همین صفحه بالاتر ببر.',
  'volume.meter': 'حجم',
  'volume.meterHint': 'آنچه از آخرین شروع دوبارهٔ شمارنده تا حالا دانلودش تمام شده، در برابر سقفِ صفحهٔ تنظیمات دانلودها. عدد وقتی تغییر می‌کند که دانلودی تمام شود، نه وقتی در حال اجراست. از تاریخچهٔ دانلودها جمع زده می‌شود، پس خالی کردن آن تاریخچه این شمارنده را هم صفر می‌کند.',
