  'settings.downloads.idleArmHint': 'اگر این صفحه را وقتی ذخیره کنی که صف از پیش خالی است، شمارش معکوس همان لحظه شروع می‌شود. منتظر تمام‌شدن دور بعدی نمی‌ماند.',
