  'idleAction.problem.empty': 'هیچ برنامه‌ای وارد نشده، پس چیزی اجرا نمی‌شود. مسیر کامل برنامه را بالا بنویس.',
  'idleAction.problem.notFound': '{program} روی این نمونه وجود ندارد.',
  'idleAction.problem.notFoundContainer': '{program} در این کانتینر وجود ندارد. اینجا فقط همان چیزی هست که ایمیج با خود می‌آورد: نه systemd، نه curl، نه ssh، نه sudo. فرمان را روی میزبان بگذار و از اینجا فراخوانش کن، یا اینجا به اسکریپتی اشاره کن که در کانتینر سوارش کرده‌ای.',
  'idleAction.problem.notExecutable': '{path} هست، اما اجرا نمی‌شود. بیت اجرا را روی آن بگذار و مطمئن شو کاربری که این فرآیند با آن اجرا می‌شود می‌تواند فایل را بخواند: در کانتینر این uid 1000 است، نه root.',
  'idleAction.problem.permission': 'سیستم رد کرد: این فرآیند اجازهٔ این کار را ندارد. در کانتینر با uid 1000 اجرا می‌شود، بدون root و بدون هیچ دسترسی به میزبان. پس هر چیزی که وضعیت برق دستگاه را عوض می‌کند باید روی خودِ میزبان انجام شود.',
  'idleAction.problem.timeout': 'برنامه پس از {seconds} ثانیه هنوز در حال اجرا بود و متوقف شد. خیلی هم ممکن است کارش را با این حال انجام داده باشد. اگر قرار است فرمان بیشتر طول بکشد، حد را بالاتر بگذار.',
