  'idleAction.problem.suspendRefused': 'سیستم خواباندن را رد کرد. در لینوکس معمولاً مدیر سیاست‌ها تأییدی می‌خواهد که این برنامه نمی‌تواند بدهد: خواباندن را برای کاربرت مجاز کن، یا روی «اجرای یک فرمان» بگذار و دستگاه را با اسکریپت خودت بخوابان.',
