  'settings.transfer.cardTitle': 'پشتیبان‌گیری و انتقال',
  'settings.transfer.cardHint': 'هر دو فایل اینجا نوشته می‌شوند و مرورگرت آن‌ها را ذخیره می‌کند، جای دیگری نمی‌روند. هیچ‌کدام ورودهای دبرید و هاسترت، پروفایل‌های سرایند، کلیدهای کپچا، گذرواژهٔ ورود به این رابط یا اسکریپت‌هایت را با خود نمی‌برد: این‌ها رمزگذاری‌شده بیرون از settings.json می‌نشینند و بایگانی هم آن‌ها را جا می‌گذارد، پس روی دستگاه تازه از نو برپایشان می‌کنی.',
  'settings.transfer.archiveLabel': 'کل نصب',
  'settings.transfer.archiveText': 'یک بایگانی با هر چه روی این دستگاه هست: پایگاه‌داده، فهرست دانلودها، تاریخچه و تنظیمات، همراه با گذرواژه‌ها، پس فایل را جایی خصوصی نگه دار. بازیابی همهٔ این‌ها را جایگزین می‌کند و از راه‌اندازی بعدی اثر می‌گذارد.',
  'settings.transfer.settingsLabel': 'فقط تنظیمات',
  'settings.transfer.settingsText': 'فقط settings.json: محدودیت‌های صف، پوشه‌ها، قواعد، دسته‌ها و زمان‌بندی. هنگام ورود ابتدا هر کلید را می‌بینی، تنها چیزی نوشته می‌شود که تیک می‌زنی و بی‌درنگ و بدون راه‌اندازی مجدد اثر می‌کند.',
  'settings.transfer.export': 'برون‌ریزی تنظیمات',
  'settings.transfer.import': 'درون‌ریزی تنظیمات',
  'settings.transfer.withSecrets': 'گذرواژه‌های ذخیره‌شده هم همراه بروند',
  'settings.transfer.withSecretsHint': 'روشن: فایل گذرواژهٔ روتر، هر گذرواژهٔ پروکسی و هر گذرواژهٔ آرشیو را به‌صورت متن ساده در خود دارد. خاموش: این کادرها روی دستگاه دیگر خالی می‌رسند و یک بار خودت واردشان می‌کنی. در هر دو حالت باز هم ممکن است رازی جایی نشسته باشد که اینجا کسی نمی‌شناسدش: نشانی فیدی که کلید API در آن است، یا گذرواژه‌ای که در یک اسکریپت اتصال دوباره نوشته‌ای.',
