  'settings.eventTargets.droppedHint': 'موجی که تندتر از آنچه این مقصد می‌گیرد برسد دور انداخته می‌شود و نگه داشته نمی‌شود، چون نگه داشتنش یعنی خرج کردن حافظه برای پیام‌هایی که تا برسند کهنه شده‌اند. اگر این عدد همچنان بالا برود، این مقصد برای رویدادهایی که نشان‌دار کرده‌ای کند است.',
  'settings.eventTargets.problem.noUrl': 'در این ردیف نشانی‌ای نیست، پس چیزی فرستاده نمی‌شود. بالا یکی بنویس.',
  'settings.eventTargets.problem.badUrl': 'این نشانی به‌عنوان نشانی http یا https خوانده نمی‌شود. طرح و میزبان را بررسی کن.',
  'settings.eventTargets.problem.badMethod': 'این بیلد GET و POST و PUT می‌فرستد و بس. یکی از این سه را برگزین.',
  'settings.eventTargets.problem.badTemplate': 'یک جانگهدار بسته نشده است. هر کدام با دو علامت درصد در دو طرف نام نوشته می‌شود.',
  'settings.eventTargets.problem.unknownTrigger': 'یکی از رویدادهای این ردیف رویدادی نیست که این بیلد به راه بیندازد. نشانش را بردار و یکی از فهرست برگزین.',
  'settings.eventTargets.problem.dns': 'میزبان از درون این نمونه حل نشد. کانتینر اغلب نام‌سرویس خودش را دارد، پس نشانی‌ای که رایانهٔ خودت به آن می‌رسد لزوماً نشانی‌ای نیست که این جعبه به آن برسد.',
  'settings.eventTargets.problem.refused': 'آنجا چیزی گوش نمی‌دهد. درگاه را بررسی کن و اینکه آن سرویس اصلاً در حال اجراست یا نه.',
  'settings.eventTargets.problem.tls': 'گواهی پذیرفته نشد. معمولاً پای یک گواهی خودامضا روی سرور خودت در میان است. در شبکهٔ خودت http را بگذار، یا گواهی را به این کانتینر بده.',
  'settings.eventTargets.problem.timeout': 'طرف مقابل درون حد زمانی پاسخ نداد. حد بالا را بیشتر کن، یا به چیزی سریع‌تر بفرست.',
  'settings.eventTargets.problem.auth': 'طرف مقابل گواهی‌های دسترسی را رد کرد. توکن را در سرایندها بررسی کن، و یادت باشد که بازهدایت به میزبان دیگر سرایند Authorization را در راه دور می‌اندازد.',
  'settings.eventTargets.problem.notFound': 'طرف مقابل چنین مسیری ندارد. در ntfy موضوع بخشی از نشانی است، در Matrix شناسهٔ اتاق.',
  'settings.eventTargets.problem.rejected': 'طرف مقابل درخواست را خواند و ردش کرد. پاسخ پایین لفظ خودِ اوست و بیشتر از هر دسته‌بندی‌ای اینجا می‌گوید.',
  'settings.eventTargets.problem.rateLimited': 'طرف مقابل همین حالا رد می‌کند، چون یک‌باره زیادی رسید. رویدادهای پرسروصداتر را بردار، یا به سرور خودت بفرست و نه به یک سرور عمومی.',
  'settings.eventTargets.problem.server': 'طرف مقابل با خطای خودش پاسخ داد. به همان تعداد که این ردیف اجازه می‌دهد دوباره تلاش شد، پس جای بعدی برای نگاه کردن گزارش خودِ اوست.',
