  'settings.health.titleHint': 'این صفحه فقط می‌خواند. هیچ‌چیز روی آن چیزی را شروع، متوقف یا عوض نمی‌کند، و باز گذاشتنش هم چیزی را عوض نمی‌کند. مقادیر هر ده ثانیه یک بار گرفته می‌شوند؛ گرفتنی که ناکام بماند آخرین خوانده‌شده را سر جایش می‌گذارد، به‌جای اینکه صفحه را خالی کند. بخش‌هایی که باید از آن‌ها پرسیده شود نیم دقیقه به اشتراک گذاشته می‌شوند، پس آنچه اینجا می‌بینی می‌تواند تا سی ثانیه از ردیف‌های صفحهٔ دانلودها عقب باشد.',
  'settings.health.version': 'نسخه',
  'settings.health.uptime': 'مدت اجرا',
  'settings.health.uptimeHint': 'اینکه این فرایند چقدر در حال اجراست، نه اینکه دستگاه چقدر بالا بوده است. کانتینری که یک ساعت پیش از نو راه‌اندازی شده اینجا دوباره از صفر شروع می‌کند، میزبان هر چه بگوید. تاریخ کنارش ساعت خودِ سرور است، نه ساعت مرورگر تو.',
