  'settings.health.oldHealthHint': 'نشانی قدیمی /api/health تغییری نکرده و تا وقتی این فرایند بالاست همچنان «ok» پاسخ می‌دهد، هر چه این صفحه بگوید. این‌طور می‌ماند چون بررسی سلامت کانتینر، پل Click\'n\'Load و جست‌وجوی اپ گوشی برای نمونه‌های شبکه‌ات همه آن را می‌خوانند، و پاسخی جز «ok» کانتینر را ناسالم علامت می‌زد و باعث می‌شد گوشی دیگر این نمونه را پیدا نکند. خطا در این صفحه گزارش می‌شود؛ آن نشانی فقط می‌گوید چیزی گوش می‌دهد یا نه.',
