  'health.part.captcha': 'کپچاها',
  'health.remedy.store.failed': 'پایگاه‌داده پاسخ نداد. دانلودها به کار خود ادامه می‌دهند، اما دیگر چیزی دربارهٔ آن‌ها نوشته نمی‌شود، پس یک راه‌اندازی مجدد هر چه را از آن زمان عوض شده از دست می‌دهد. بررسی کن که پوشهٔ داده هنوز سوار است و هنوز می‌شود در آن نوشت.',
  'health.remedy.jd.unreachable': 'KL_JD نشانی‌ای را نام می‌برد که این نمونه همین حالا به آن نمی‌رسد. بررسی کن که کانتینر JDownloader در حال اجراست و درگاه API آن از اینجا پاسخ می‌دهد. پیوندهایی که تنها JDownloader می‌تواند بگیرد تا آن موقع در صف می‌مانند؛ آن‌ها شکست نخورده‌اند.',
  'health.remedy.jd.notWired': 'JDownloader دوباره پاسخ می‌دهد، اما این فرایند پشتوانه‌هایش را هنگام راه‌اندازی به هم بست و آن موقع این یکی را نداشت. KnightLoader را از نو راه‌اندازی کن تا برداشته شود.',
  'health.remedy.ytdlp.missing': 'هنگام راه‌اندازی این فرایند هیچ yt-dlp پیدا نشد (KL_YTDLP، یا "yt-dlp" روی PATH). صفحه‌های رسانه آن‌وقت با خطای خودِ سایت شکست می‌خورند، به‌جای اینکه به گونه‌های گوناگون باز شوند. برای پیدا شدنش یک راه‌اندازی مجدد لازم است.',
  'health.remedy.disk.low': 'یک پوشهٔ مقصد زیر کفی است که در صفحهٔ دانلودها گذاشته‌ای. تا وقتی دوباره جا باز نشود یا کف را پایین نیاوری، آنجا چیز تازه‌ای شروع نمی‌شود. آنچه از پیش در حال اجراست با آن کف متوقف نمی‌شود.',
  'health.remedy.disk.elsewhere': 'یک پوشه آنجا نیست، پس عددها نزدیک‌ترین پوشهٔ بالاتر را توصیف می‌کنند. اگر چیزی سوار نشده باشد، آن یک دیسک کاملاً دیگر است. پیش از آنکه عددها را باور کنی، به مسیر نگاه کن.',
  'health.remedy.accounts.benched': 'دست‌کم یک حساب هاستر پس از یک خطا به حال خود رها شده است. وقتی انتظار تمام شود، خودش یک بار دیگر امتحان می‌شود، و انتظار هر بار دو برابر می‌شود. اگر همین حالا می‌خواهی بدانی، حساب‌ها را باز کن و روی آن ردیف تازه‌سازی را بزن.',
  'health.remedy.accounts.invalid': 'دست‌کم یک حساب هاستر رد شد. یک کلید تازه یا اشتراکی تمدیدشده این را درست می‌کند؛ انتظار نه.',
  'health.remedy.feeds.failing': 'آخرین گرفتنِ دست‌کم یک اشتراک شکست خورد. اینکه کدام و چرا، در صفحهٔ دانلودها کنار فید نوشته شده، و در خطوط گزارش روی صفحهٔ عیب‌یابی.',
  'health.remedy.relay.down': 'یک نشانی رله ذخیره شده و اتصال برقرار نیست. این نمونه خودش دوباره تلاش می‌کند و هر چیزی که محلی است مثل همیشه کار می‌کند؛ تنها رسیدن به آن از بیرون کار نمی‌کند.',
  'health.remedy.captcha.waiting': 'یک پشتوانه ایستاده تا از یک آدم بپرسد. تا کسی پاسخ ندهد، هیچ‌چیز پشت آن تکان نمی‌خورد.',
  'settings.health.tasks': 'دانلودها همین حالا',
  'settings.health.tasksHint': 'یک عکس لحظه‌ای از فهرست همان‌طور که هست، نه شمارشی در طول زمان، پس هیچ‌کدام از این عددها نمی‌گوید چیزی چند بار شکست خورده. «شکست‌خورده» ردیف‌هایی را می‌شمارد که با یک خطا در فهرست هستند: وقتی پاکشان کنی و وقتی فهرست پس از روزهایی که تنظیم کرده‌ای مرتب شود پایین می‌آید، و وقتی چیز تازه‌ای خراب شود دوباره بالا می‌رود.',
