  'settings.health.diskLink': 'اینکه روی پوشه‌های مقصد چقدر جا هست، در صفحهٔ دانلودها نوشته شده',
  'settings.health.scrape': 'پایش',
  'settings.health.scrapeSwitch': 'روی نشانی مقادیر پاسخ بده',
  'settings.health.scrapeHint': 'نشانی دومی باز می‌کند که همان مقادیر را به‌صورت متن ساده می‌دهد، در همان قالبی که Prometheus و ابزارهای ساخته‌شده به شکل آن می‌خوانند. گرفته می‌شود، هرگز فرستاده نمی‌شود: تا وقتی پایش خودت اینجا نیاید و آن را نخواهد، هیچ‌چیز این دستگاه را ترک نمی‌کند. تا وقتی این خاموش است، آن نشانی اصلاً وجود ندارد و با 404 پاسخ می‌دهد، درست مثل هر نشانی دیگری که این برنامه ندارد. روی نمونه‌ای که گذرواژه دارد، گرفتنِ آن به یکی از توکن‌های API تو نیاز دارد، و می‌شود به هر گردآورنده‌ای یاد داد که یکی بفرستد. یک گردآورنده سرایند مبدأ نمی‌فرستد و برای همین از سد می‌گذرد؛ یک تب مرورگر روی نشانی دیگر یکی می‌فرستد و اگر با نشانی خودِ این نمونه نخواند پذیرفته نمی‌شود. در آن متن مسیرهای پوشه‌های مقصد تو نوشته‌اند، پس آن را تنها جایی بده که نام خودِ پوشه‌ها را هم می‌دادی.',
  'settings.health.scrapeUrl': 'نشانی مقادیر',
  'settings.health.scrapeCopy': 'کپی نشانی',
  'settings.health.scrapeCopied': 'نشانی کپی شد',
  'settings.health.scrapeOffHint': 'تا وقتی کلید بالا خاموش است، این نشانی هیچ پاسخی نمی‌دهد.',
  'settings.diagnostics.systemTitle': 'اطلاعات سامانه',
  'settings.diagnostics.fileTitle': 'فایل گزارش',
  'settings.diagnostics.fileOn': 'گزارش در یک فایل نوشته شود',
  'settings.diagnostics.fileOnHint': 'خاموش است تا خودت روشنش کنی، و یک به‌روزرسانی هرگز آن را برایت روشن نمی‌کند. روشن که باشد، این نمونه هر خطی را که ثبت می‌کند در فایلی در پوشهٔ دادهٔ خود می‌نویسد، تا فروپاشی پریشب پس از یک راه‌اندازی مجدد هنوز خواندنی باشد. یک خط گزارش می‌تواند نشانی فیدی را که مشترکش شده‌ای نام ببرد، پس با آن فایل مثل مال خودت رفتار کن. در کانتینر همان خطوط از پیش به docker logs می‌رسند؛ فایل همان چیزی است که پس از رد شدن آن‌ها باقی می‌ماند.',
