  'settings.diagnostics.fileKeepHint': 'چند فایل تغییرنام‌یافته کنار فایلی که در حال نوشته شدن است می‌مانند. صفر فقط فایل فعلی را نگه می‌دارد؛ گزارش را خاموش نمی‌کند.',
