  'settings.diagnostics.logSourceHint': 'اینکه یک خط از کدام بخش برنامه آمده است، خوانده‌شده از آغاز خودِ خط. خطی که هیچ بخشی را نام نبرد زیر «باقی خطوط» می‌نشیند. درجهٔ اهمیتی برای فیلتر کردن وجود ندارد: در این برنامه هیچ‌چیز یکی را ثبت نمی‌کند.',
