  'settings.owner.identityTitle': 'این نمونه به نام چه کسی می‌نویسد',
  'settings.owner.identityHint': 'هر فایلی که این نمونه می‌سازد همین مالک و همین دسترسی‌ها را می‌گیرد، و هر چه راه می‌اندازد هم همین‌طور: yt-dlp، ffmpeg و JDownloaderِ همراه. در کانتینر، هویت همان لحظه‌ای که کانتینر شروع می‌شود تثبیت می‌گردد، با همان حسابی که کانتینر زیر آن راه‌اندازی شده، و هیچ‌چیز در این صفحه نمی‌تواند عوضش کند.',
