  'settings.owner.envHow': 'اگر می‌خواهی زیر حساب دیگری اجرا شود، آن را در فرمان راه‌اندازی نام ببر: --user <uid>:<gid>. روی Unraid این در Extra Parameters می‌رود، و کانتینر باید از نو ساخته شود تا اثر کند.',
  'settings.owner.desktopNote': 'برنامهٔ دسکتاپ زیر حساب خودت اجرا می‌شود. PUID و PGID و UMASK تنظیمات کانتینرند و اینجا هیچ کاری نمی‌کنند.',
  'settings.owner.noOwners': 'روی این سامانه فایل‌ها مالک ندارند، پس چیزی برای مقایسه نیست. این خطا نیست.',
  'settings.owner.checkTitle': 'بررسی پوشه‌ها',
  'settings.owner.checkHint': 'اینجا واقعاً یک فایل و یک زیرپوشه در هر پوشه نوشته می‌شود، بعد خوانده می‌شود که هر دو به که تعلق دارند و چه کس دیگری اجازهٔ خواندنشان را دارد، و بعد هر دو دوباره برداشته می‌شوند. این را باید اندازه گرفت و نمی‌شود حسابش کرد: یک اشتراک می‌تواند قواعد دسترسی خودش را با خود بیاورد، و پوشه‌ای که set-group-id روی آن نشسته گروهی دیگر می‌دهد تا آنکه این فرایند دارد. این بررسی پس از ذخیرهٔ پوشه‌ای که عوض کرده‌ای خودش اجرا می‌شود، و هر بار که دکمه را بزنی.',
  'settings.owner.run': 'همین حالا پوشه‌ها را بررسی کن',
  'settings.owner.running': 'در حال بررسی…',
