  'settings.owner.v.ok': 'فایل‌ها اینجا به‌عنوان {fileOwner} با {fileMode} می‌نشینند، زیرپوشه‌های تازه با {subdirMode}، و خودِ پوشه به {dirOwner} تعلق دارد. در این هیچ‌چیز به چشم نمی‌آید.',
  'settings.owner.v.ownerMismatch': 'فایل‌ها اینجا به‌عنوان {fileOwner} می‌نشینند، اما پوشه به {dirOwner} تعلق دارد. خواندنشان معمولاً هنوز کار می‌کند؛ تغییر نام، جابه‌جایی و حذفشان از حسابی دیگر نه، و هر چیزی که انتظار دارد پوشه مالک محتوای خودش باشد، این فایل‌ها را بیگانه می‌شمارد.',
