  'settings.owner.fix.user': 'کانتینر را زیر همان حسابی راه بینداز که پوشه به آن تعلق دارد: --user {dirUid}:{dirGid} در فرمان راه‌اندازی. روی Unraid این در Extra Parameters می‌رود.',
