  'settings.resolvers.toolsYtdlpMissingHint': 'بدون yt-dlp اصلاً بک‌اند رسانه‌ای وجود ندارد: پیوندی به یک صفحهٔ ویدیو به‌جای دانلود شدن با خطای خودِ سایت رد می‌شود. در کانتینر از بستهٔ yt-dlp همان ایمیج می‌آید؛ روی دسکتاپ خودت نصبش می‌کنی و یا روی PATH می‌گذاری‌اش یا KL_YTDLP را روی آن می‌گذاری. اگر هیچ‌کدام از این دو ممکن نبود، دکمهٔ پایین خودش یک کپی می‌آورد.',
  'settings.resolvers.toolsFfmpegMissingHint': 'بدون ffmpeg، yt-dlp نمی‌تواند ردهای جدای تصویر و صدا را که بیشتر سایت‌ها تحویل می‌دهند به هم بپیوندد، پس دانلود یا به‌شکل یک ردِ ویدیوی بی‌صدا می‌نشیند یا یکسره شکست می‌خورد. بدون ffprobe، «بررسی فایل تمام‌شده» بالاتر در همین صفحه چیزی را اندازه نمی‌گیرد و چیزی هم دربارهٔ آن نمی‌گوید. در کانتینر هر دو از همان بستهٔ ffmpeg می‌آیند که ایمیج نصب می‌کند؛ روی دسکتاپ خودت نصبشان می‌کنی و روی PATH می‌گذاری‌شان.',
  'settings.resolvers.toolsShadowed': 'کپی خودِ KnightLoader در حال اجراست. تا وقتی آن هست، KL_YTDLP و PATH راه‌اندازی نمی‌شوند: به‌جایش {path} به کار می‌رفت، و آن {version} را گزارش می‌کند.',
  'settings.resolvers.toolsShadowedOlder': 'حواست باشد: کپی‌ای که KnightLoader آورده ({current}) از آنچه از پیش روی این دستگاه هست ({system}، در {path}) قدیمی‌تر است. به‌روزرسانی کانتینر yt-dlp تازه‌تری با خود می‌آورد، و کپی خودت با آن جابه‌جا نمی‌شود. یکی تازه بیاور، یا به کپی سامانه برگرد.',
